  const PAL = { k: '#000', w: '#fff', g: '#3a9a2a', G: '#1f5e14', l: '#8ad84a', r: '#e10600', R: '#8a0000', y: '#ffd400', Y: '#b08a00', b: '#2a7ad8', B: '#0028c8', c: '#9fd0ff', C: '#00e5ff', o: '#ff8000', p: '#ff8ac0', s: '#f2c79a', S: '#c8956a', n: '#7a4a1a', N: '#4a2a0a', a: '#9a9a9a', A: '#555', e: '#c8c8c8', d: '#e8e0c8', D: '#b8ae90', t: '#008080', m: '#c0187a', v: '#5b16c9', u: '#fff3b0', i: '#203060', h: '#ff4040' };

