    telegraph: p => { room(p); p.rect(12, 30, 40, 6, '#7a4a1a'); p.rect(12, 30, 40, 1, '#9a6a3a'); p.rect(18, 24, 24, 3, '#c8a040'); p.rect(40, 20, 6, 4, '#222'); p.disc(43, 19, 3, '#111'); p.rect(20, 27, 3, 3, '#c8a040'); p.rect(30, 26, 2, 4, '#888'); p.line(12, 32, 0, 32, '#333'); p.text(4, 6, '... --- ...', '#203060'); },
