    vhs: p => { carpet(p); p.rect(6, 10, 52, 28, '#111'); p.rect(6, 10, 52, 2, '#333'); p.rect(14, 15, 36, 12, '#333'); p.rect(16, 17, 32, 8, '#222'); p.disc(22, 21, 3, '#555').disc(42, 21, 3, '#555'); p.rect(25, 19, 14, 4, '#3a2a1a'); p.rect(10, 29, 44, 6, '#f8f8f8'); p.text(12, 30, 'RECORD', '#e10600'); },
