    // ---------------- Y2K and time
    y2k: p => { p.vgrad(0, 48, '#300010', '#800020'); p.rect(8, 8, 26, 30, '#fff'); p.rect(8, 8, 26, 7, '#e10600'); p.text(10, 9, 'DEC', '#fff'); p.text(14, 18, '31', '#000', 2); p.text(12, 30, '1999', '#000'); p.ell(48, 26, 8, 6, '#3a9a2a'); p.disc(42, 22, 4, '#3a9a2a'); p.px(41, 21, '#fff').px(43, 21, '#fff').px(41, 21, '#000'); for (let i = 0; i < 3; i++) { p.line(44 + i * 4, 30, 42 + i * 4, 35, '#1f5e14'); p.line(44 + i * 4, 22, 42 + i * 4, 18, '#1f5e14'); } p.line(40, 19, 37, 15, '#1f5e14').line(43, 18, 44, 14, '#1f5e14'); p.text(40, 38, 'Y2K', '#ffd400', 2); },
