    grot: p => { p.vgrad(0, 48, '#fff8dc', '#ffe8a0'); const c = '#3a9a2a', d = '#1f5e14'; p.poly([[14, 14], [2, 6], [8, 20]], c); p.poly([[50, 14], [62, 6], [56, 20]], c); p.ell(32, 18, 16, 13, c); p.ell(25, 15, 4, 3, '#fff').ell(39, 15, 4, 3, '#fff'); p.rect(25, 14, 2, 2, '#e10600').rect(38, 14, 2, 2, '#e10600'); p.rect(22, 23, 20, 5, '#000'); for (let x = 23; x < 42; x += 3) p.rect(x, 23, 2, 2, '#fff'); p.ell(32, 40, 12, 8, '#7a4a1a'); p.line(18, 18, 18, 30, d); },
